from bk import write, leadgen_block, ad, SITE
from pages_core import GUIDES, card

def article(slug, title, desc, tag, ages, mins, toc, body, sources, related):
    tocl = "".join(f'<li><a href="#s{i+1}">{t}</a></li>' for i, t in enumerate(toc))
    src = "".join(f"<li>{s}</li>" for s in sources)
    rel = "".join(card(h, tg, "", t, d) for related_slug in related for h, tg, t, d, m in GUIDES if h.endswith(related_slug + ".html"))
    schema = {"@context": "https://schema.org", "@type": "Article", "headline": title, "description": desc, "author": {"@type": "Organization", "name": "BetterKid Editorial Team"}, "publisher": {"@type": "Organization", "name": "BetterKid.com", "url": SITE}, "mainEntityOfPage": f"{SITE}/guides/{slug}.html", "datePublished": "2026-09-27", "dateModified": "2026-09-27"}
    html = f'''
<div class="progress" style="position:sticky;top:68px;z-index:99;border-radius:0;height:4px"><span data-read-progress style="width:0"></span></div>
<section class="section-tight"><div class="wrap article">
<div class="crumbs"><a href="{{r}}">Home</a> › <a href="{{r}}guides/">Guides</a> › {tag}</div>
<span class="tag">{tag}</span> <span class="tag age">Ages {ages}</span>
<h1 style="margin-top:12px">{title}</h1>
<p class="lead">{desc}</p>
<div class="byline"><span>By the BetterKid Editorial Team</span><span>·</span><span>{mins} min read</span><span>·</span><span>Updated Sep 2026</span><span class="reviewed">✔ Reviewed against current paediatric guidance</span></div>
<div class="toc"><strong>In this guide</strong><ol>{tocl}</ol></div>
{body}
{ad("in-article","article-mid")}
<h2>Sources</h2><ol style="font-size:.9rem;color:var(--ink-2)">{src}</ol>
<div class="share"><button class="btn btn-ghost btn-sm" data-share="native">Share</button><button class="btn btn-ghost btn-sm" data-share="whatsapp">WhatsApp</button><button class="btn btn-ghost btn-sm" data-share="pinterest">Pinterest</button><button class="btn btn-ghost btn-sm" data-share="facebook">Facebook</button><button class="btn btn-ghost btn-sm" data-share="copy">Copy link</button></div>
<p class="disclaimer">This guide is general educational information, not medical or psychological advice. If you are worried about your child, talk to your paediatrician or a qualified professional. <a href="{{r}}legal/disclaimer.html">Disclaimers</a> · Spotted an error? <a data-contact data-subject="Correction: {title}" href="#contact">Tell us</a>.</p>
</div></section>
{leadgen_block("{r}")}
<section class="section-tight"><div class="wrap"><span class="eyebrow">Keep reading</span><div class="grid g3" style="margin-top:14px">{rel}</div></div></section>'''
    write(f"/guides/{slug}.html", f"{title} | BetterKid", desc, html, f"guide {tag.lower()} {slug.replace('-', ' ')}", schema=schema)

def H(i, t): return f'<h2 id="s{i}">{t}</h2>'
def TK(items): return '<div class="takeaway"><h3>Key takeaways</h3><ul>' + "".join(f"<li>{x}</li>" for x in items) + "</ul></div>"

def build():
    # index
    cards = "".join(card(h, tg, "", t, d, meta=f"<span>Ages {m}</span>") for h, tg, t, d, m in GUIDES)
    write("/guides/", "Parenting guides: behavior, sleep, screens, reading, money & more | BetterKid", "Evidence-based parenting guides in plain English, with sources, for ages 3–12 and teens.", f'''
<section class="hero"><div class="wrap"><span class="eyebrow">Guides</span><h1>Evidence-based, in plain English</h1><p class="lead" style="max-width:720px">Each guide answers one real question, cites its sources, and ends with something you can do tonight.</p>
<div class="pill-list" style="margin-top:14px"><a href="#behavior">Behavior</a><a href="#screens">Screens</a><a href="#sleep">Sleep</a><a href="#learning">Learning</a><a href="#money">Money</a><a href="#nutrition">Nutrition</a><a href="#social">Social</a><a href="#teens">Teens</a></div></div></section>
<section><div class="wrap grid g3">{cards}</div></section>{ad("leader","guides")}{leadgen_block("{r}")}''', "guides articles")

    article("tantrums-and-big-feelings", "Tantrums & big feelings: the 4-step script that actually calms a child", "Why tantrums happen, what's going on in the brain, and the exact words that shorten them — without giving in.", "Behavior", "3–8", 7,
        ["Why tantrums happen", "The 4-step script", "What not to do", "When to seek help"],
        H(1, "Why tantrums happen (and why it isn't manipulation)") + "<p>Between roughly 18 months and 6 years, a child's emotional brain (the limbic system) is fully online while the regulating part (the prefrontal cortex) is decades from finished. A tantrum is what an overwhelmed nervous system does when a want collides with a wall and the child has no other tool. Hunger, tiredness and transitions lower the threshold dramatically — most late-afternoon meltdowns are a blood-sugar and sleep problem wearing a behaviour costume.</p><p>Frequency data is reassuring: in a University of Wisconsin community sample, ~87% of 18–24-month-olds and ~91% of 30–36-month-olds had tantrums; by 42–48 months it drops to ~59%. Daily tantrums lasting over 25 minutes, or that regularly involve hurting others, are the outliers worth a conversation with your paediatrician.</p>"
        + H(2, "The 4-step script") + "<ol><li><strong>Get low and quiet.</strong> Kneel to eye level, drop your voice. Your calm is the loan they borrow against.</li><li><strong>Name it, don't fix it.</strong> “You really wanted the blue cup. You're so mad.” Labelling an emotion measurably reduces amygdala activation — in adults and children.</li><li><strong>Hold the line, softly.</strong> “I'm not going to change my answer, and I'm right here.” The limit stays; the relationship stays.</li><li><strong>Offer a bridge when the wave passes.</strong> “Do you want to carry the cup or should I?” Choice restores a sense of control and ends the episode faster than a lecture.</li></ol><blockquote>Connection before correction. You can't teach a brain that's flooded — teach after.</blockquote>"
        + H(3, "What not to do") + "<ul><li><strong>Don't reason mid-storm.</strong> Language processing is offline. Save the explanation for later.</li><li><strong>Don't give in to end it.</strong> Every tantrum that “works” teaches the brain that it's an effective tool. Consistency is kinder in the long run.</li><li><strong>Don't punish the feeling.</strong> Punish (or rather, set consequences for) hitting or throwing — never for being upset.</li><li><strong>Don't take it personally.</strong> They melt down with you because you're safe. That's a compliment with terrible timing.</li></ul>"
        + H(4, "When to seek help") + "<p>Talk to your paediatrician if tantrums happen daily past age 5, routinely last more than 20–25 minutes, involve self-injury, or your child can't calm down even with support. Persistent explosive behaviour can be a sign of language delay, sensory issues, anxiety or ADHD — all of which respond well to early support.</p>"
        + TK(["Tantrums are overflow, not strategy — expect them 3–5×/week at 2–4.", "Calm body → name the feeling → keep the limit → offer a choice.", "Prevent with snacks, sleep and 2-minute transition warnings.", "Daily 25-minute tantrums past age 5 warrant a check-up."])
        + f'<p><a class="btn btn-teal" href="{{r}}printables/#calm-down">Download the Calm-Down Cards printable →</a></p>',
        ["Potegal M, Davidson RJ. Temper tantrums in young children: 1. Behavioral composition. <em>J Dev Behav Pediatr</em> 2003.", "Wakschlag LS et al. Defining the developmental parameters of temper loss in early childhood. <em>J Child Psychol Psychiatry</em> 2012.", "Lieberman MD et al. Putting feelings into words: affect labeling disrupts amygdala activity. <em>Psychol Sci</em> 2007.", "American Academy of Pediatrics, HealthyChildren.org — Temper Tantrums."],
        ["bedtime-routine", "building-confidence-and-resilience", "screen-time-rules-that-work"])

    article("screen-time-rules-that-work", "Screen-time rules that work (and survive the weekend)", "A budget, not a ban. What the guidelines actually say by age, why quality beats quantity, and how to set limits kids accept.", "Screens", "3–12", 8,
        ["What the guidelines say", "Budget, don't ban", "The 5 rules that hold", "Phones and first devices"],
        H(1, "What the guidelines actually say") + "<p>The American Academy of Pediatrics no longer publishes a single hours number for kids over 5. Their guidance: under 18 months, avoid except video chat; 18–24 months, high-quality programming watched together; 2–5 years, about 1 hour/day of quality content, co-viewed; 6+, <em>consistent limits</em> that protect sleep, physical activity and face-to-face time. The WHO adds: under-5s should not be sedentary in front of a screen for more than an hour a day.</p><p>What the research consistently shows is that <strong>displacement</strong> is the problem, not the pixels: screens hurt when they replace sleep, play, reading and conversation. That reframes your job from “police the minutes” to “protect the must-dos”.</p>"
        + H(2, "Budget, don't ban") + f"<p>Start from 24 hours. Subtract sleep (9–12 h for 6–12s), school, meals, homework, activities and outdoor play. What's left is discretionary time — and recreational screens should take about a third of it, capped by age. Our <a href='{{r}}tools/screen-time-budget.html'>Screen-Time Budget tool</a> does this in 30 seconds and produces a visual your child can understand. Kids accept limits they can <em>see</em>.</p>"
        + H(3, "The 5 rules that hold") + "<ol><li><strong>Must-dos first.</strong> Screens come after homework, movement and chores — automatically, every day, no negotiation.</li><li><strong>No screens in bedrooms overnight.</strong> This single rule has the largest measured effect on sleep and mood. Devices charge in the kitchen.</li><li><strong>Screen-free meals.</strong> For everyone. Parental phone use at the table predicts children's phone use more than any rule.</li><li><strong>Content over clock.</strong> An hour building in Minecraft with a friend is not an hour of autoplay shorts. Distinguish creating, connecting and consuming.</li><li><strong>Write it down.</strong> A signed family media agreement cuts arguments because the rule — not the parent — is the authority.</li></ol>"
        + H(4, "Phones and first devices") + "<p>Median age of first smartphone in North America is now about 11. There's no magic age; there is a readiness test: can they follow existing screen rules without policing, lose a privilege gracefully, and tell you when something online feels wrong? Start with a “dumb” phone or a watch, and layer capabilities as trust is earned. Set parental controls before handing it over — retro-fitting them is a fight.</p>"
        + TK(["Guidelines: ~1 h quality content at 2–5; consistent limits after 6.", "Displacement, not screens, is the harm — protect sleep, play, reading.", "Devices out of bedrooms overnight is the highest-impact rule.", "Use a written agreement so the rule is the authority, not you."])
        + f'<p><a class="btn btn-teal" href="{{r}}tools/screen-time-budget.html">Build your family\'s screen-time budget →</a> <a class="btn btn-ghost" href="{{r}}printables/#screen-time-contract">Printable media agreement →</a></p>',
        ["AAP Council on Communications and Media. Media and Young Minds / Media Use in School-Aged Children and Adolescents. <em>Pediatrics</em> 2016.", "WHO. Guidelines on physical activity, sedentary behaviour and sleep for children under 5 years of age. 2019.", "Common Sense Media. The Common Sense Census: Media Use by Tweens and Teens, 2021.", "Carter B et al. Association between portable screen-based media device access or use and sleep outcomes. <em>JAMA Pediatr</em> 2016."],
        ["bedtime-routine", "homework-without-tears", "talking-to-teens"])

    article("bedtime-routine", "The bedtime routine that ends the nightly battle", "How much sleep kids need by age, why routine beats willpower, and a 45-minute wind-down that sticks within two weeks.", "Sleep", "3–12", 6,
        ["How much sleep kids need", "Why routines work", "The 45-minute wind-down", "Troubleshooting"],
        H(1, "How much sleep kids actually need") + "<p>The American Academy of Sleep Medicine consensus (endorsed by the AAP): 3–5 years, 10–13 hours including naps; 6–12 years, 9–12 hours; 13–18 years, 8–10 hours. Most school-age kids in surveys get 1–2 hours less than the low end. Chronic short sleep looks exactly like ADHD, anxiety and “attitude” — which is why we recommend fixing sleep before treating anything else.</p>"
        + H(2, "Why routines beat willpower") + "<p>A consistent bedtime routine is one of the best-evidenced interventions in paediatrics: across a study of 10,000+ families in 14 countries, each additional night per week with a routine predicted earlier bedtimes, faster sleep onset, fewer wakings and longer sleep — with a dose-response effect. The routine works because the brain learns a chain of cues: bath → PJs → books → song → dark. By the third step, melatonin is already rising.</p>"
        + H(3, "The 45-minute wind-down") + f"<p>Work backwards from the wake time you need (our <a href='{{r}}tools/sleep-calculator.html'>Sleep Calculator</a> does this):</p><ol><li><strong>T-45: screens off, lights down.</strong> Blue light suppresses melatonin; dimming the house is a physiological cue.</li><li><strong>T-40: bath or wash, PJs, teeth.</strong> The post-bath temperature drop is itself sleep-inducing.</li><li><strong>T-20: two books (or one chapter).</strong> Same spot, same order. For 9–12s, independent reading in bed with a lamp.</li><li><strong>T-5: same goodnight phrase, every night.</strong> “Goodnight, I love you, see you in the morning.” Predictability is the point.</li><li><strong>Lights out.</strong> Leave. Return briefly and boringly if needed.</li></ol>"
        + H(4, "Troubleshooting") + "<ul><li><strong>Endless requests (water, one more hug):</strong> give a “bedtime pass” — one card, redeemable once, then done.</li><li><strong>Fear of the dark:</strong> a dim warm nightlight, a “monster check” done seriously, and a worry box for tomorrow.</li><li><strong>Refuses to stay in bed:</strong> silent, calm returns. No talking. Studies show it takes 3–7 nights of consistency.</li><li><strong>Tweens who aren't tired:</strong> melatonin timing shifts later at puberty. Protect the morning: consistent wake-up and daylight within 30 minutes reset the clock.</li></ul>"
        + TK(["3–5: 10–13 h · 6–12: 9–12 h · teens: 8–10 h.", "Consistency of routine predicts better sleep in a dose-response way.", "Screens off 45 minutes before lights-out; devices out of the bedroom.", "Use a bedtime pass and boring returns for stalling."]),
        ["Paruthi S et al. Recommended amount of sleep for pediatric populations: AASM consensus statement. <em>J Clin Sleep Med</em> 2016.", "Mindell JA et al. Bedtime routines for young children: a dose-dependent association with sleep outcomes. <em>Sleep</em> 2015.", "Hale L, Guan S. Screen time and sleep among school-aged children and adolescents. <em>Sleep Med Rev</em> 2015."],
        ["tantrums-and-big-feelings", "screen-time-rules-that-work", "homework-without-tears"])

    article("raising-a-reader", "Raising a reader: 10 minutes a day, ages 3–12", "What the research says builds reading (and what doesn't), by age — plus how to handle a kid who says reading is boring.", "Learning", "3–12", 7,
        ["Why 10 minutes matters", "Ages 3–5: sounds and stories", "Ages 6–8: the take-off", "Ages 9–12: keeping them reading"],
        H(1, "Why ten minutes matters so much") + "<p>Reading volume compounds. A child who reads 20 minutes a day encounters roughly 1.8 million words a year; 5 minutes a day yields about 280,000. Vocabulary, background knowledge and comprehension follow that curve. Being read <em>to</em> counts: kids read to daily from birth hear over a million more words by kindergarten than kids who aren't.</p>"
        + H(2, "Ages 3–5: sounds and stories") + "<p>The two predictors of later reading are <strong>phonological awareness</strong> (hearing the sounds in words) and <strong>oral language</strong>. Rhyming games, clapping syllables, “what sound does <em>ball</em> start with?” — all in play. Read the same books repeatedly (repetition builds vocabulary better than novelty), point at words occasionally, and talk about the pictures. Skip flashcard drills; they don't help at this age.</p>"
        + H(3, "Ages 6–8: the take-off") + "<p>The science of reading is settled on this: systematic phonics (explicitly teaching letter-sound correspondence and blending) beats guessing from pictures or context. If your child's school uses “three-cueing”, supplement at home with decodable books. Practise 10 minutes: 5 with them reading aloud to you, 5 with you reading something a level above them. Let them re-read favourites — fluency comes from repetition. Graphic novels count. Audiobooks count.</p>"
        + H(4, "Ages 9–12: keeping them reading") + "<p>Reading for pleasure falls off a cliff at 9–11, especially for boys. Antidotes: <strong>choice</strong> (anything — sports almanacs, Minecraft guides, manga), <strong>a series</strong> (the next book removes the decision), <strong>reading in bed</strong> as the only allowed way to stay up later, <strong>your own visible reading</strong>, and a library card with zero pressure. Never make reading a punishment or a chore-for-reward.</p>"
        + TK(["Volume compounds — 20 min/day ≈ 1.8M words a year.", "3–5: sounds, rhymes, repeated read-alouds. No flashcards.", "6–8: systematic phonics + daily practice + re-reading.", "9–12: choice, series, reading-in-bed privilege, your example."])
        + f'<p><a class="btn btn-teal" href="{{r}}printables/#reading-log">Printable reading log →</a></p>',
        ["Anderson RC, Wilson PT, Fielding LG. Growth in reading and how children spend their time outside of school. <em>Reading Research Quarterly</em> 1988.", "Logan JAR et al. When children are not read to at home: the million word gap. <em>J Dev Behav Pediatr</em> 2019.", "National Reading Panel. Teaching Children to Read. 2000.", "Castles A, Rastle K, Nation K. Ending the reading wars. <em>Psychol Sci Public Interest</em> 2018."],
        ["homework-without-tears", "building-confidence-and-resilience", "screen-time-rules-that-work"])

    article("chores-and-allowance", "Chores & allowance: the 3-jar method", "Which chores at which age, whether to tie money to chores, and how to teach spending, saving and giving with three jars.", "Money", "5–12", 6,
        ["Why chores matter", "Chores by age", "Allowance: pay or not?", "The 3-jar method"],
        H(1, "Why chores matter more than grades") + "<p>The Harvard Grant Study — the longest-running study of adult development — found that doing chores in childhood was one of the strongest predictors of professional success and wellbeing decades later. A University of Minnesota analysis found that starting chores at 3–4 predicted higher self-competence and academic achievement in the mid-20s. Chores teach the thing school can't: that you are a contributor, not a customer.</p>"
        + H(2, "Chores by age") + "<table><tr><th>Age</th><th>Realistic chores</th></tr><tr><td>3–5</td><td>Put toys away, put clothes in hamper, feed pet (with help), wipe table, match socks, water plants</td></tr><tr><td>6–8</td><td>Make bed, set/clear table, sort laundry, empty small bins, pack own school bag, simple food prep</td></tr><tr><td>9–12</td><td>Load/unload dishwasher, vacuum, fold laundry, cook one simple meal, take out rubbish, pet care fully, mow/rake with supervision</td></tr></table><p>Rule: expect it to take longer and be done worse than you'd do it. That's the cost of tuition.</p>"
        + H(3, "Allowance: pay for chores or not?") + "<p>Two defensible camps. <strong>Unpaid family chores + a separate allowance</strong> (recommended by most financial educators): chores are what family members do; allowance is a tool to learn money. <strong>Paid chores</strong>: money is earned, not given. Our position: baseline chores unpaid, allowance unconditional, with <em>optional extra jobs</em> for extra money. The typical rate is roughly $0.50–$1 per year of age per week.</p>"
        + H(4, "The 3-jar method") + f"<p>Split every payment: <strong>Spend 50%</strong> (small wants, their call, mistakes allowed), <strong>Save 30%</strong> (a named goal with a picture on the jar), <strong>Give 20%</strong> (a cause they choose). Use clear jars — visible money is the lesson. At 9+, move Save to a real account and show them the statement. Our <a href='{{r}}tools/allowance-calculator.html'>Allowance Calculator</a> works out the split and projects the savings.</p>"
        + TK(["Chores in childhood predict adult wellbeing and success.", "Start at 3 with tiny jobs; scale responsibility, not nagging.", "Baseline chores unpaid; allowance unconditional; extra jobs paid.", "Spend 50 / Save 30 / Give 20 in clear jars."])
        + f'<p><a class="btn btn-teal" href="{{r}}tools/chore-chart.html">Build a printable chore chart →</a></p>',
        ["Vaillant GE. Triumphs of Experience: The Men of the Harvard Grant Study. 2012.", "Rossmann M. Involving children in household tasks: is it worth the effort? University of Minnesota, 2002.", "White EM et al. Associations between household chores and childhood self-competency. <em>J Dev Behav Pediatr</em> 2019."],
        ["homework-without-tears", "building-confidence-and-resilience", "raising-a-reader"])

    article("healthy-eating-kids", "Feeding kids without food fights", "The division of responsibility, the science of picky eating, and a no-drama dinner plan you can start tonight.", "Nutrition", "3–12", 6,
        ["Division of responsibility", "Picky eating is normal", "The no-drama dinner", "Red flags"],
        H(1, "The division of responsibility") + "<p>Dietitian Ellyn Satter's framework is the most widely endorsed approach in paediatric nutrition: <strong>parents decide what, when and where</strong>; <strong>children decide whether and how much</strong>. That means you serve balanced meals on a schedule; you do not negotiate bites, bribe with dessert or make a second dinner. Kids raised this way eat more variety by age 8 than kids who were pressured — the pressure itself is what backfires.</p>"
        + H(2, "Picky eating is normal (and usually temporary)") + "<p>Food neophobia peaks between 2 and 6 — an evolutionary safety feature when toddlers start roaming. Research shows it can take 10–15 neutral exposures before a child accepts a new food. “Neutral” is the key word: on the plate, no comment. Serve one new or disliked food alongside two accepted ones every time. Around 20% of children are picky at 4; well under 5% still are at 10.</p>"
        + H(3, "The no-drama dinner plan") + "<ol><li>Eat together at a table, screens off, at roughly the same time daily.</li><li>Family-style serving: bowls in the middle, kids serve themselves (tiny portions are fine).</li><li>One “safe” food you know they'll eat is always on the table (bread, rice, fruit).</li><li>Dessert, if served, is served with the meal, not as a reward. It de-fetishises sugar within weeks.</li><li>Kitchen closes after dinner except for a set, boring bedtime snack.</li><li>Talk about anything except the food.</li></ol>"
        + H(4, "When to get help") + "<p>See a paediatrician or dietitian if your child eats fewer than ~20 foods and is dropping foods, gags or vomits with new textures, is falling off their growth curve, or if mealtimes are consistently distressing. These can indicate sensory feeding issues or ARFID, which respond well to early feeding therapy.</p>"
        + TK(["You control what/when/where; they control whether/how much.", "10–15 neutral exposures before acceptance is normal.", "Serve dessert with dinner; never as a reward.", "Fewer than ~20 accepted foods or growth concerns → get help."]),
        ["Satter E. Ellyn Satter's Division of Responsibility in Feeding. Ellyn Satter Institute.", "Dovey TM et al. Food neophobia and 'picky/fussy' eating in children: a review. <em>Appetite</em> 2008.", "Taylor CM, Emmett PM. Picky eating in children: causes and consequences. <em>Proc Nutr Soc</em> 2019."],
        ["tantrums-and-big-feelings", "bedtime-routine", "chores-and-allowance"])

    article("friendships-and-bullying", "Friendships, conflict & bullying: what to do at each age", "How friendship works at 6, 9 and 12, how to coach social skills without hovering, and exactly when and how to step in on bullying.", "Social", "6–12", 7,
        ["How friendship changes by age", "Coaching, not fixing", "Normal conflict vs bullying", "What to do about bullying"],
        H(1, "How friendship changes by age") + "<p>At 5–7, a friend is “someone I play with” — friendships are activity-based and change weekly. At 8–10, loyalty, secrets and fairness appear; being left out starts to hurt. At 11–12, friendships become intimate and identity-defining; social hierarchies sharpen and group belonging feels like survival. Knowing the stage stops you over-reacting to a Tuesday fallout at 7 and under-reacting to exclusion at 11.</p>"
        + H(2, "Coaching, not fixing") + "<p>Kids with strong social skills have parents who <em>coach</em> — talk through situations afterwards — rather than <em>manage</em> — intervene in the moment. Three scripts worth rehearsing: joining (“Can I play? What are the rules?”), disagreeing (“I don't like that. Let's do X instead.”), and exiting (“I'm going to go play over there.”). Host playdates at your house early on; you'll see the dynamics and the child gets home-court advantage.</p>"
        + H(3, "Normal conflict vs bullying") + "<p>Conflict is two roughly equal kids in a dispute — it's healthy and how they learn. <strong>Bullying is repeated, intentional, and involves a power imbalance</strong>. About 20% of students report being bullied in a given year; cyberbullying rises sharply from 10. Signs: dreading school, unexplained injuries or lost items, sleep changes, sudden phone secrecy.</p>"
        + H(4, "What to do about bullying") + "<ol><li><strong>Listen fully before reacting.</strong> Kids stop talking when parents explode or minimise.</li><li><strong>Don't tell them to hit back or ignore it.</strong> Neither works. Teach a calm, firm response plus walking towards an adult or group.</li><li><strong>Document</strong> dates, what happened, who saw it. Screenshot everything online.</li><li><strong>Contact the school in writing</strong>, ask for their anti-bullying policy and a plan with a follow-up date.</li><li><strong>Build the bench:</strong> one out-of-school friendship group (sport, club, cousins) is the single strongest protective factor.</li></ol><p>If your child is the one bullying: treat it as a skills and empathy problem, not a character verdict — and look at what's going on at home.</p>"
        + TK(["Friendship is activity-based at 6, loyalty-based at 9, identity-based at 12.", "Coach afterwards; rehearse joining, disagreeing and exiting scripts.", "Bullying = repeated + intentional + power imbalance.", "Document, contact school in writing, build an outside friendship group."]),
        ["National Center for Education Statistics. Student Reports of Bullying: Results from the School Crime Supplement. 2022.", "Rubin KH, Bukowski WM, Laursen B (eds). Handbook of Peer Interactions, Relationships, and Groups. 2018.", "StopBullying.gov (U.S. Department of Health and Human Services)."],
        ["building-confidence-and-resilience", "talking-to-teens", "homework-without-tears"])

    article("homework-without-tears", "Homework without tears", "The 10-minute rule, how to set up focus, when to help and when not to, and how to talk to the teacher when it's too much.", "School", "6–12", 6,
        ["How much is enough", "Set-up that creates focus", "Help without doing", "Talking to the teacher"],
        H(1, "How much homework is enough?") + "<p>The research-backed “10-minute rule” endorsed by the National PTA and NEA: about 10 minutes per grade level per night (Grade 1 = 10 min, Grade 6 = 60 min). Meta-analyses find <strong>no measurable achievement benefit</strong> from homework in elementary school beyond building habits, and a modest benefit in middle school that flattens beyond ~90 minutes. If your 8-year-old is doing an hour, something is wrong — with the task, the set-up, or the assignment.</p>"
        + H(2, "Set-up that creates focus") + "<ul><li><strong>Same time, same place.</strong> After a snack and 20–30 minutes of movement — not straight off the bus.</li><li><strong>Body-doubling.</strong> Younger kids work better at the kitchen table while you cook than alone in a bedroom.</li><li><strong>Timer, not nagging.</strong> Set 15–20 minutes, then a real break. The timer is the boss.</li><li><strong>Phone in another room.</strong> Mere presence of a phone reduces working memory — even face-down.</li><li><strong>Start with the hardest task</strong> while energy is highest; finish with the easy win.</li></ul>"
        + H(3, "Help without doing") + "<p>Your role is scaffolding, not scribe. Ask “what's the first step?” and “what do you already know?” before explaining. If they're stuck, work one example together, then hand back. Never correct all the errors — the teacher needs to see them. And when it's clearly too hard or too long, stop, write a note to the teacher, and let it go. A protected relationship is worth more than a completed worksheet.</p>"
        + H(4, "Talking to the teacher") + "<p>Email, don't ambush. “Homework is taking 60 minutes and ending in tears most nights. Is that what you expect? What should we prioritise if we run out of time?” Most teachers will tell you to stop at the time limit. Ask about accommodations if focus is a consistent struggle — you don't need a diagnosis to request them.</p>"
        + TK(["~10 minutes per grade level per night. More has no measurable benefit in elementary.", "Snack + movement first; same spot; timer as boss; phone elsewhere.", "Ask questions, don't give answers; leave errors for the teacher.", "Email the teacher early when it's too much — they usually agree."]),
        ["Cooper H, Robinson JC, Patall EA. Does homework improve academic achievement? A synthesis of research 1987–2003. <em>Rev Educ Res</em> 2006.", "National PTA / National Education Association homework guidance.", "Ward AF et al. Brain drain: the mere presence of one's own smartphone reduces available cognitive capacity. <em>J Assoc Consum Res</em> 2017."],
        ["raising-a-reader", "screen-time-rules-that-work", "building-confidence-and-resilience"])

    article("building-confidence-and-resilience", "Building confidence & resilience", "Growth mindset done properly, the praise that helps and the praise that hurts, and why letting kids struggle is a gift.", "Character", "3–12", 6,
        ["Confidence comes from competence", "Praise that helps vs hurts", "Let them struggle (safely)", "Growth mindset, minus the hype"],
        H(1, "Confidence comes from competence, not compliments") + "<p>Self-esteem programmes that tell kids they're special don't move outcomes; <strong>mastery experiences</strong> do. Children feel capable when they do hard things and succeed — tying laces, riding a bike, cooking an egg, making a phone call. Every job you do for them that they could do themselves is a small withdrawal from confidence.</p>"
        + H(2, "Praise that helps vs praise that hurts") + "<p>Carol Dweck's studies found children praised for being “smart” chose easier tasks afterwards and lied about scores more; children praised for <em>effort and strategy</em> chose harder tasks and persisted. Swap “You're so clever” for “You tried three different ways until it worked.” Swap “Good job” for a specific description: “You shared without being asked.” Description is information; evaluation is pressure.</p>"
        + H(3, "Let them struggle — safely") + "<p>Resilience is built by recovering from manageable setbacks, not by avoiding them. The forgotten lunch, the lost match, the friend who was mean, the wobbly first day — resist rescuing. Instead: empathise (“That was hard”), then hand it back (“What do you want to do about it?”). Anxiety research is clear: accommodation (removing every stressor) increases anxiety over time; supported exposure decreases it.</p>"
        + H(4, "Growth mindset, minus the hype") + "<p>The replication picture is mixed: growth-mindset interventions produce small average effects, larger for lower-achieving students. What holds up: teaching kids that the brain gets stronger with practice, normalising mistakes as information, and modelling it yourself (“I got that wrong — let me try again”). What doesn't: posters, slogans and praising effort on tasks that were actually easy.</p>"
        + TK(["Competence → confidence. Let them do what they can do.", "Praise effort, strategy and specifics — not intelligence.", "Empathise, then hand the problem back.", "Model mistakes and recovery out loud."]),
        ["Mueller CM, Dweck CS. Praise for intelligence can undermine children's motivation and performance. <em>J Pers Soc Psychol</em> 1998.", "Sisk VF et al. To what extent and under which circumstances are growth mind-sets important to academic achievement? Two meta-analyses. <em>Psychol Sci</em> 2018.", "Lebowitz ER et al. Parent-based treatment as efficacious as CBT for childhood anxiety (SPACE). <em>J Am Acad Child Adolesc Psychiatry</em> 2020."],
        ["tantrums-and-big-feelings", "friendships-and-bullying", "chores-and-allowance"])

    article("talking-to-teens", "Talking to teens so they actually talk back", "Autonomy-supportive parenting, the 80/20 listening rule, side-by-side conversations and the mental-health red flags every parent should know.", "Teens", "13+", 7,
        ["What changes at 13", "The 80/20 rule", "Autonomy with guardrails", "Mental-health red flags"],
        H(1, "What changes at 13") + "<p>Adolescence rewires the social brain: peer approval activates reward circuitry as strongly as food, and the drive for autonomy is biological, not attitude. Teens still want parents — surveys consistently show parents remain their most trusted source on big issues — but on their terms: fewer questions, more presence, less judgement.</p>"
        + H(2, "The 80/20 rule") + "<p>Listen 80%, talk 20%. Open with “do you want advice or do you just want to vent?” — it hands over control and doubles the odds they keep talking. Side-by-side beats face-to-face: driving, cooking, walking the dog. Late evenings are when teens open up; be around, put your phone down, and don't pounce.</p>"
        + H(3, "Autonomy with guardrails") + "<p>Decades of research on parenting styles converge: <strong>authoritative</strong> parenting — warm, high expectations, explains reasons, involves the teen in rules — beats authoritarian (control without warmth) and permissive (warmth without limits) on nearly every outcome, from grades to substance use to mental health. Practically: fewer rules, clearly explained, consistently enforced, renegotiated as trust grows. Privacy expands with responsibility, and you say that out loud.</p>"
        + H(4, "Mental-health red flags") + "<p>Roughly one in five adolescents experiences a diagnosable anxiety or mood disorder; most go untreated for years. Watch for: withdrawal from friends and activities they used to love; sleep collapse (too much or too little); sudden drop in grades; irritability that lasts weeks; changes in eating; giving away possessions; talk of hopelessness or being a burden. Any of these lasting more than two weeks warrants a conversation with their doctor <em>that week</em>. If your teen mentions suicide, take it seriously, stay calm, ask directly, and contact a crisis line or emergency services if there's immediate risk.</p>"
        + TK(["Autonomy-seeking is biology; you remain their most trusted source.", "Ask “advice or vent?” Listen 80%. Talk side-by-side.", "Authoritative beats strict and permissive on every outcome.", "Two weeks of withdrawal, sleep collapse or hopelessness → doctor this week."]),
        ["Steinberg L. Age of Opportunity: Lessons from the New Science of Adolescence. 2014.", "Pinquart M. Associations of parenting dimensions and styles with internalizing/externalizing problems: meta-analyses. <em>Dev Psychol</em> 2017.", "Merikangas KR et al. Lifetime prevalence of mental disorders in U.S. adolescents (NCS-A). <em>J Am Acad Child Adolesc Psychiatry</em> 2010.", "American Academy of Pediatrics. Mental Health Initiatives / Bright Futures guidance."],
        ["screen-time-rules-that-work", "building-confidence-and-resilience", "bedtime-routine"])
